function makeArticle(cluster, row) {
  const [slug, title, decision, procedure, example, failure, metric] = row;
  const focus = title.split(':')[0].split('?')[0].toLocaleLowerCase('pt-BR');
  return {
    slug, title,
    description: `${decision}. Veja um procedimento, exemplo aplicado, risco e indicador para decidir melhor.`,
    category: cluster.category, date: '2026-11-11', updated: '2026-11-11',
    featured: false, keywords: [focus, cluster.category.toLocaleLowerCase('pt-BR')],
    intro: `${decision}. Este guia complementa a página principal do tema com uma decisão operacional específica. O exemplo é ilustrativo; adapte o procedimento às fontes, permissões e condições reais da sua empresa.`,
    takeaways: [decision, procedure, `Acompanhe: ${metric.toLocaleLowerCase('pt-BR')}.`],
    sections: [
      { heading: 'A decisão que precisa ser tomada', paragraphs: [
        `${decision}. ${example} Esse recorte evita tratar uma jornada inteira como se fosse uma única tarefa. Anote qual evento inicia o caso, quem responde pelo próximo passo e qual informação comprova que ele terminou.`,
      ] },
      { heading: 'Procedimento aplicável', paragraphs: [
        `${procedure} Execute primeiro em uma amostra limitada, incluindo um caso comum, uma exceção e uma falha de integração ou informação. Registre o resultado esperado antes de automatizar e peça à equipe que confira os casos em que a regra não foi suficiente.`,
      ] },
      { heading: 'Limite e verificação', paragraphs: [
        `${failure} Defina uma saída segura para esse cenário e um responsável pela correção. A medida principal é ${metric.toLocaleLowerCase('pt-BR')}; compare o mesmo tipo de caso antes e depois da mudança, mantendo visíveis custo, espera e intervenções humanas.`,
      ] },
    ],
    faqs: [{ question: `Qual é o primeiro passo para ${focus}?`, answer: `${procedure} Comece com poucos casos e ajuste com base nas falhas observadas.` }],
    sources: cluster.sourceKeys.map((key) => sources[key]),
    primaryGuide: { href: cluster.parent, label: cluster.parent === '/' ? 'Tironi Tech' : 'guia principal', description: 'Continue pelo contexto completo no' },
    cta: cluster.cta,
  };
}

export const searchConsoleExpansionArticles = clusters.flatMap((cluster) => cluster.topics.map((row) => makeArticle(cluster, row)));
